with scored as (select id, customer_id, start_date, end_date, status, min(monthly_fee) over (partition by status order by start_date, id rows between 3 preceding and current row) as last4_min_monthly_fee, sum(monthly_fee) over (partition by status order by start_date, id rows between 3 preceding and current row) as last4_sum_monthly_fee, avg(monthly_fee) over (partition by status order by start_date, id rows between 3 preceding and current row) as last4_avg_monthly_fee, round(monthly_fee / sum(monthly_fee) over (partition by plan), 4) as monthly_fee_share from subscriptions where customer_id = 22) select id, customer_id, start_date, status, last4_avg_monthly_fee, monthly_fee_share, case when status rlike '^(ACTIVE|PAUSED)$' then 'GROUP_A' when status rlike '^(CANCELLED|EXPIRED)$' then 'GROUP_B' else 'EXTENDED' end as status_zone from scored order by monthly_fee_share nulls last
